70:       </aside>
71:     </main>
72:     <footer><span>© YOUR CARTRIDGE, YOUR QUEST &nbsp;·&nbsp; LOCAL PLAY ONLY</span><span class="footer-right">No ROM included. Game files must be supplied by the player.</span></footer>
73:   </div>
74:   <script type="module">
75:     const $ = (s) => document.querySelector(s);
76:     const canvas = $('#gameCanvas');
77:     const ctx = canvas.getContext('2d', { alpha: false });
78:     const image = ctx.createImageData(256, 240);
79:     let emulator = null, core = null, paused = false, running = false, lastTick = 0, carry = 0, frameId = 0;
80:     const buttonNames = {UP:'BUTTON_UP',DOWN:'BUTTON_DOWN',LEFT:'BUTTON_LEFT',RIGHT:'BUTTON_RIGHT',A:'BUTTON_A',B:'BUTTON_B',START:'BUTTON_START',SELECT:'BUTTON_SELECT'};
81:     const keyMap = {ArrowUp:'UP',ArrowDown:'DOWN',ArrowLeft:'LEFT',ArrowRight:'RIGHT',z:'B',Z:'B',x:'A',X:'A',Enter:'START',Shift:'SELECT'};
82:     const held = new Set();
83:     function setStatus(text, active=false){$('#statusText').textContent=text;$('#statusDot').style.background=active?'#a5cf74':'#a0a083';$('#statusDot').style.boxShadow=active?'0 0 9px #a5cf74':'0 0 8px #999';$('#screenState').textContent=active?(paused?'PAUSED':'LIVE'):'NO SIGNAL';}
84:     function renderFrame(frame){
85:       const out=image.data;
86:       for(let i=0,j=0;i<frame.length;i++,j+=4){const pixel=frame[i];out[j]=(pixel>>>16)&255;out[j+1]=(pixel>>>8)&255;out[j+2]=pixel&255;out[j+3]=255;}
87:       ctx.putImageData(image,0,0);
88:     }
89:     function loop(now){
90:       if(!running)return;
91:       frameId=requestAnimationFrame(loop);
92:       if(paused||!emulator)return;
93:       if(!lastTick)lastTick=now;
94:       carry+=Math.min(100,now-lastTick);lastTick=now;
95:       while(carry>=16.67){emulator.frame();carry-=16.67;}
96:     }
97:     function loadCore(){
98:       if(core)return Promise.resolve(core);
99:       return import('https://esm.sh/jsnes@1.2.1').then(mod=>{
100:         const api=mod.default||mod;
101:         core={NES:mod.NES||api.NES,Controller:mod.Controller||api.Controller};
102:         if(!core.NES)throw new Error('The NES emulator library could not be initialized.');
103:         return core;
104:       });
105:     }
106:     function readBinary(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const bytes=new Uint8Array(reader.result);let binary='';const chunkSize=0x8000;for(let i=0;i<bytes.length;i+=chunkSize)binary+=String.fromCharCode(...bytes.subarray(i,i+chunkSize));resolve(binary);};reader.onerror=()=>reject(new Error('Could not read that file.'));reader.readAsArrayBuffer(file);});}
107:     async function insert(file){
108:       if(!file)return;
109:       $('#errorMsg').style.display='none';
110:       if(!file.name.toLowerCase().endsWith('.nes')){showError('That does not look like a .nes file. Choose an NES ROM.');return;}
111:       if(file.size<16){showError('This cartridge file is too small to be a valid NES ROM.');return;}
112:       if(file.size>16*1024*1024){showError('This ROM is larger than this player supports (16 MB max).');return;}
113:       setStatus('LOADING CARTRIDGE');$('#screenState').textContent='LOADING';
114:       try{
115:         const [binary,loadedCore]=await Promise.all([readBinary(file),loadCore()]);
116:         if(binary.slice(0,4)!=='NES\x1a')throw new Error('Invalid NES header. Select a valid .nes ROM file.');
117:         $('#idle').style.display='none';canvas.style.display='block';
118:         emulator=new loadedCore.NES({onFrame:renderFrame,onAudioSample:()=>{}});
119:         emulator.loadROM(binary);
120:         paused=false;running=true;lastTick=0;carry=0;
121:         $('#pauseBtn').disabled=false;$('#resetBtn').disabled=false;$('#pauseBtn').textContent='Ⅱ  PAUSE';
122:         $('#gameName').textContent=file.name;$('#romFileName').textContent=file.name;
123:         setStatus('CARTRIDGE READY',true);
124:         if(frameId)cancelAnimationFrame(frameId);frameId=requestAnimationFrame(loop);
125:       }catch(err){emulator=null;running=false;canvas.style.display='none';$('#idle').style.display='grid';setStatus('AWAITING CARTRIDGE');showError(err.message||'Unable to start this ROM.');}
126:     }
127:     function showError(text){const el=$('#errorMsg');el.textContent=text;el.style.display='block';}
128:     function fire(name,down){if(!emulator||!core?.Controller)return;const code=core.Controller[buttonNames[name]];if(code===undefined)return;try{if(down)emulator.buttonDown(1,code);else emulator.buttonUp(1,code);}catch{}}
129:     function keyDown(e){const name=keyMap[e.key];if(!name)return;e.preventDefault();if(!held.has(name)){held.add(name);fire(name,true);}}
130:     function keyUp(e){const name=keyMap[e.key];if(!name)return;e.preventDefault();held.delete(name);fire(name,false);}
131:     $('#chooseRom').addEventListener('click',()=>$('#romInput').click());$('#browseBtn').addEventListener('click',()=>$('#romInput').click());
132:     $('#romInput').addEventListener('change',e=>{insert(e.target.files[0]);e.target.value='';});
133:     $('#screen').addEventListener('dragover',e=>{e.preventDefault();$('#screen').style.outline='2px dashed #e4c76d';});
134:     $('#screen').addEventListener('dragleave',()=>$('#screen').style.outline='');
135:     $('#screen').addEventListener('drop',e=>{e.preventDefault();$('#screen').style.outline='';insert(e.dataTransfer.files[0]);});
136:     window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
137:     window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>{for(const name of held)fire(name,false);held.clear();});
138:     $('#pauseBtn').addEventListener('click',()=>{if(!emulator)return;paused=!paused;$('#pauseBtn').textContent=paused?'▶  RESUME':'Ⅱ  PAUSE';setStatus('CARTRIDGE READY',true);});
139:     $('#resetBtn').addEventListener('click',()=>{if(!emulator)return;const rom=emulator.romData;try{emulator.reset();}catch{if(rom)emulator.loadROM(rom);}paused=false;$('#pauseBtn').textContent='Ⅱ  PAUSE';setStatus('CARTRIDGE READY',true);});
140:     $('#fullscreenBtn').addEventListener('click',()=>{const el=$('#screen');if(document.fullscreenElement)document.exitFullscreen?.();else el.requestFullscreen?.();});
141:     document.querySelectorAll('[data-button]').forEach(btn=>{const name=btn.dataset.button;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);fire(name,true);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,e=>{e.preventDefault();fire(name,false);});});
142:     document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){paused=true;$('#pauseBtn').textContent='▶  RESUME';setStatus('CARTRIDGE READY',true);}});
143:   </script>
144: </body>
145: </html>

